sys_script_include.script:
var ManagerUtils = Class.create();
ManagerUtils.prototype = {
    initialize: function() {
    },

    // Função para obter gerentes válidos
    getValidManagers: function() {
        var validManagers = [];  // Array para armazenar os sys_id dos gerentes válidos
        var finalValidManagers = [];

        // Passo 1: Query na tabela sys_user para encontrar os gerentes com a role específica
        var grUser = new GlideRecord('sys_user');
        grUser.addQuery('roles', 'dd2b1a3783b31210889d5e20ceaad340'); // Role específica
        grUser.query();

        while (grUser.next()) {
            validManagers.push(grUser.sys_id.toString());
        }

        // Passo 2: Query para verificar quais gerentes não estão associados a nenhuma base
        var grBase = new GlideRecord('x_1593183_bases_base'); // Nome da tabela de bases
        grBase.query();

        // Cria um array para armazenar gerentes que já estão associados a uma base
        var managersWithBase = [];

        while (grBase.next()) {
            var managerSysId = grBase.manager.sys_id.toString(); // sys_id do gerente
            if (managersWithBase.indexOf(managerSysId) == -1) {
                managersWithBase.push(managerSysId); // Adiciona o gerente à lista dos que já tem base
            }
        }

        // Passo 3: Agora, selecionamos apenas os gerentes válidos que **não** estão na lista de gerentes com base
        for (var i = 0; i < validManagers.length; i++) {
            var managerSysId = validManagers[i];
            if (managersWithBase.indexOf(managerSysId) == -1) {
                finalValidManagers.push(managerSysId); // Adiciona o gerente se ele não tem base
            }
        }

        // Retorna os sys_ids dos gerentes válidos que não estão associados a nenhuma base
        return "sys_idIN" + finalValidManagers.join(',');
    },

    type: 'ManagerUtils'
};
